CREATE TABLE districts AS SELECT * FROM (VALUES
  ('Downtown', ST_GeomFromText('POLYGON((0 0, 10 0, 10 10, 0 10, 0 0))')),
  ('Uptown',   ST_GeomFromText('POLYGON((10 0, 20 0, 20 10, 10 10, 10 0))'))
) t(district_name, geom);

CREATE TABLE stores AS SELECT * FROM (VALUES
  ('Alpha Mart',  ST_Point(2, 2),  120000),
  ('Beta Shop',   ST_Point(5, 5),  340000),
  ('Gamma Store', ST_Point(8, 3),  210000),
  ('Delta Mart',  ST_Point(12, 4), 500000),
  ('Epsilon Co',  ST_Point(15, 8), 150000),
  ('Zeta Corner', ST_Point(18, 2), 430000)
) t(store_name, geom, revenue);
